const { TIPOS_ALERTA, MODOS_ENVIO, COLUMNAS_ALERTAS, LIMITE_TELEGRAM, marcaTiempoSistema, limpiarTexto, generarIdAlerta, modoAlertaCalidad, textoAlertaOperativa, textoAlertaCalidad, textoAlertaCosto, textoAlertaCalibracion, erroresCriticosDeEvaluacion, prepararAlertasCalidad, armarResumenCalidadLote, armarAlertaCosto, armarAlertaCalibracion, armarAlertaOperativa, alertasDeEvaluacion, alertaCostoLoteCopia, cierreDeLote, cierrePorLotes, debeAlertar, estadoEnvio, filaAlertas } = __fuente_alertas;

