  const fecha = marca.slice(0, 10).replace(/-/g, '');
  const hora = marca.slice(11, 19).replace(/:/g, '');
  return `${prefijo}-${fecha}-${hora}-${String(consecutivo).padStart(3, '0')}`;
}

