    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase();
}

function workflowDesdeNombre(nombre, palabras = PALABRAS_WORKFLOW) {
  const n = sinAcentos(nombre);
  const encontrada = palabras.find(([palabra]) => n.includes(palabra));
  return encontrada ? encontrada[1] : 'errores';
