  // `conversaciones` pasa a `reproceso` (solo estado y actualizado_en). Misma forma que
  // actualizacionEstadoEvaluacion(llave, 'reproceso', config, ahora) de js/ingesta.js (prueba de igualdad).
  let actualizacion = null;
