  if (workflowEnum === 'evaluacion' && llave && opciones.config) {
    actualizacion = {
      llave_dedup: llave,
      estado: 'reproceso',
      actualizado_en: marcaTiempoSistema(opciones.ahora || new Date(), opciones.config.zona_horaria),
